import { defineStore } from 'pinia';
import { computed, ref } from 'vue';
import { EstablishmentApi } from '../infrastructure/establishment-api.js';
import { EstablishmentAssembler } from '../infrastructure/establishment.assembler.js';
import { OperatorAssembler } from '../infrastructure/operator.assembler.js';

const establishmentApi = new EstablishmentApi();

const useEstablishmentStore = defineStore('establishment', () => {
    const establishments = ref([]);
    const operators = ref([]);
    const errors = ref([]);
    const establishmentsLoaded = ref(false);
    const operatorsLoaded = ref(false);

    const establishmentsCount = computed(() => (
        establishmentsLoaded.value ? establishments.value.length : 0
    ));

    const operatorsCount = computed(() => (
        operatorsLoaded.value ? operators.value.length : 0
    ));

    async function fetchEstablishmentsAsync() {
        try {
            const response = await establishmentApi.getEstablishments();
            establishments.value = EstablishmentAssembler.toEntitiesFromResponse(response);
            establishmentsLoaded.value = true;
            return establishments.value;
        } catch (error) {
            errors.value.push(error);
            return [];
        }
    }

    function fetchEstablishments() {
        fetchEstablishmentsAsync();
    }

    async function fetchOperatorsAsync() {
        try {
            const response = await establishmentApi.getOperators();
            operators.value = OperatorAssembler.toEntitiesFromResponse(response);
            operatorsLoaded.value = true;
            return operators.value;
        } catch (error) {
            errors.value.push(error);
            return [];
        }
    }

    function fetchOperators() {
        fetchOperatorsAsync();
    }

    async function createEstablishmentAsync(payload) {
        const response = await establishmentApi.createEstablishment(payload);
        const created = EstablishmentAssembler.toEntityFromResource(response.data);
        establishments.value = [...establishments.value, created];
        establishmentsLoaded.value = true;
        return created;
    }

    function getEstablishmentById(id) {
        const idNum = parseInt(id, 10);
        return establishments.value.find((establishment) => establishment.id === idNum);
    }

    function getOperatorById(id) {
        const idNum = parseInt(id, 10);
        return operators.value.find((operator) => operator.id === idNum);
    }

    async function createOperatorAsync(payload) {
        const response = await establishmentApi.createOperator(payload);
        const created = OperatorAssembler.toEntityFromResource(response.data);
        operators.value = [...operators.value, created];
        operatorsLoaded.value = true;
        return created;
    }

    async function updateOperatorAsync(payload) {
        const response = await establishmentApi.updateOperator(payload);
        const updated = OperatorAssembler.toEntityFromResource(response.data);
        const index = operators.value.findIndex((o) => o.id === updated.id);
        if (index !== -1) operators.value[index] = updated;
        return updated;
    }

    async function assignOperatorsToEstablishmentAsync({ userIds, establishmentId }) {
        const estId = Number(establishmentId);
        const results = [];
        for (const userId of userIds) {
            const uid = Number(userId);
            const existing = operators.value.find((o) => Number(o.users_id) === uid);
            if (existing) {
                const updated = await updateOperatorAsync({
                    id: existing.id,
                    users_id: existing.users_id,
                    establishment_id: estId,
                    alerts_answered: existing.alerts_answered,
                    schedule: existing.schedule,
                });
                results.push(updated);
            } else {
                const created = await createOperatorAsync({
                    users_id: uid,
                    establishment_id: estId,
                    alerts_answered: 0,
                    schedule: 'Mañana 06:00-14:00',
                });
                results.push(created);
            }
        }
        return results;
    }

    async function deleteOperatorAsync(id) {
        await establishmentApi.deleteOperator(id);
        operators.value = operators.value.filter((o) => Number(o.id) !== Number(id));
    }

    return {
        establishments,
        operators,
        errors,
        establishmentsLoaded,
        operatorsLoaded,
        establishmentsCount,
        operatorsCount,
        fetchEstablishments,
        fetchEstablishmentsAsync,
        fetchOperators,
        fetchOperatorsAsync,
        createEstablishmentAsync,
        getEstablishmentById,
        getOperatorById,
        createOperatorAsync,
        updateOperatorAsync,
        deleteOperatorAsync,
        assignOperatorsToEstablishmentAsync,
    };
});

export default useEstablishmentStore;

/**
 * Establishment value-carrying entity within the Establishment bounded context.
 *
 * @class Establishment
 */
export class Establishment {
    /**
     * @param {Object} params - Entity attributes.
     */
    constructor({
        id = null,
        establishment_name = '',
        establishment_type = '',
        address = '',
        district = '',
        city_region = '',
        country = '',
        phone = '',
        email = '',
        website = '',
        created_at = '',
        admin_id = null,
        latitude = null,
        longitude = null,
    } = {}) {
        this.id = id;
        this.establishment_name = establishment_name;
        this.establishment_type = establishment_type;
        this.address = address;
        this.district = district;
        this.city_region = city_region;
        this.country = country;
        this.phone = phone;
        this.email = email;
        this.website = website;
        this.created_at = created_at;
        this.admin_id = admin_id;
        this.latitude = latitude;
        this.longitude = longitude;
    }
}

/**
 * Operator entity within the Establishment bounded context.
 *
 * @class Operator
 */
export class Operator {
    constructor({
        id = null,
        alerts_answered = 0,
        schedule = '',
        establishment_id = null,
        users_id = null,
    } = {}) {
        this.id = id;
        this.alerts_answered = alerts_answered;
        this.schedule = schedule;
        this.establishment_id = establishment_id;
        this.users_id = users_id;
    }

    /** Normalizes any id value to a number or null. */
    static normalizeId(id) {
        if (id == null || id === '') return null;
        const n = Number(id);
        return Number.isNaN(n) ? null : n;
    }

    /**
     * Returns operator users that belong to the entity but have no /operators record yet.
     * @param {{ users: Object[], operators: Operator[], entityCode: string|null }} params
     */
    static getPendingUsers({ users, operators, entityCode }) {
        if (!entityCode) return [];
        const code = String(entityCode).trim().toUpperCase();
        const assignedUserIds = new Set(
            (operators || []).map((op) => Operator.normalizeId(op.users_id)).filter((id) => id != null),
        );
        return (users || []).filter((u) => {
            if (String(u.role || '').toUpperCase() !== 'OPERATOR') return false;
            if (String(u.entity_code || '').trim().toUpperCase() !== code) return false;
            return !assignedUserIds.has(Operator.normalizeId(u.id));
        });
    }

    /**
     * Returns operators assigned to establishments owned by a given admin.
     * @param {{ operators: Operator[], establishments: Object[], adminId: number|string|null }} params
     */
    static getAssignedForAdmin({ operators, establishments, adminId }) {
        if (adminId == null) return operators || [];
        const adminNum = Operator.normalizeId(adminId);
        const establishmentIds = new Set(
            (establishments || [])
                .filter((e) => Operator.normalizeId(e.admin_id) === adminNum)
                .map((e) => Operator.normalizeId(e.id)),
        );
        return (operators || []).filter((op) =>
            establishmentIds.has(Operator.normalizeId(op.establishment_id)),
        );
    }

    /** Formats a schedule value for display in lists and detail views. */
    static formatSchedule(schedule) {
        if (schedule == null || schedule === '') return '—';
        if (typeof schedule === 'string') return schedule;
        if (Array.isArray(schedule)) {
            if (!schedule.length) return '—';
            const first = schedule[0];
            const turn = first?.turn || first?.shift || '';
            const day = first?.day || first?.hours || first?.range || '';
            const line = [turn, day].filter(Boolean).join(' · ');
            if (!line) return '—';
            return schedule.length > 1 ? `${line} (+${schedule.length - 1})` : line;
        }
        if (typeof schedule === 'object') {
            const entries = Object.entries(schedule);
            if (!entries.length) return '—';
            const [turn, day] = entries[0];
            const line = [turn, day].filter(Boolean).join(' · ');
            return entries.length > 1 ? `${line} (+${entries.length - 1})` : line || '—';
        }
        return String(schedule);
    }
}

/**
 * Application service store for the IAM bounded context.
 * It coordinates authentication and registration use cases, exposes profile
 * state and keeps a UI-facing view of users and admins.
 *
 * @module useIamStore
 */
import { defineStore } from 'pinia';
import { computed, ref } from 'vue';
import { IamApi } from '../infrastructure/iam-api.js';
import { UserAssembler } from '../infrastructure/user.assembler.js';
import { AdminAssembler } from '../infrastructure/admin.assembler.js';
import { SignInAssembler } from '../infrastructure/sign-in.assembler.js';
import {
    readAuthSession,
    writeAuthSession,
    clearRegistrationFlow,
    readPendingRegistration,
    writePendingRegistration,
    readPendingPlan,
    writePendingPlan,
} from '../infrastructure/auth-session.js';
import { SignInCommand } from '../domain/sign-in.command.js';
import { RegisterHealthEntityCommand } from '../domain/register-health-entity.command.js';
import { RegisterOperationalStaffCommand } from '../domain/register-operational-staff.command.js';
import { Subscription } from '../../subscriptions/domain/model/subscription.entity.js';
import {
    validateDemoPayment,
    simulateDemoPaymentProcessing,
} from '../../subscriptions/domain/model/demo-payment.gateway.js';

const iamApi = new IamApi();

/**
 * Authenticates against the real backend and enriches the session with the
 * admin/operator profile linked to the user.
 * @param {SignInCommand} command - Sign-in command.
 * @returns {Promise<{ok: true, session: Object} | {ok: false, error: string}>}
 */
async function signInReal(command) {
    const response = await iamApi.signIn(command);
    const session = SignInAssembler.toSessionFromResponse(response, command.segment);
    if (!session) return { ok: false, error: 'invalidCredentials' };

    // Persist the base session so the gateway interceptor authenticates enrichment calls.
    writeAuthSession(session);

    if (session.role === 'ADMIN') {
        try {
            const admins = (await iamApi.getAdmins()).data ?? [];
            const admin = admins.find((a) => Number(a.user_id ?? a.users_id) === Number(session.userId));
            if (admin) {
                session.adminId = admin.id;
                session.entityCode = admin.entity_code;
                session.entityName = admin.entity_name;
            }
        } catch {
            // non-critical — profile loads lazily via loadProfileFromSession
        }
    }

    if (session.role === 'OPERATOR') {
        try {
            const ops = (await iamApi.getOperators()).data ?? [];
            const op = ops.find((o) => Number(o.users_id) === Number(session.userId));
            if (op) {
                session.operatorId = op.id;
                session.establishmentId = op.establishment_id ?? null;
                session.notAssigned = !op.establishment_id;
            }
        } catch {
            // non-critical
        }
    }

    writeAuthSession(session);
    return { ok: true, session };
}

const useIamStore = defineStore('iam', () => {
    const users = ref([]);
    const admins = ref([]);
    const errors = ref([]);
    const usersLoaded = ref(false);
    const adminsLoaded = ref(false);

    const profileUser = ref(null);
    const profileEstablishment = ref(null);
    const profilePlanApi = ref('BASIC');
    const profileEntityCode = ref('');
    const profileEntityName = ref('');

    const usersCount = computed(() => (usersLoaded.value ? users.value.length : 0));
    const adminsCount = computed(() => (adminsLoaded.value ? admins.value.length : 0));

    // ─── Queries ────────────────────────────────────────────────────────────────

    async function fetchUsersAsync() {
        try {
            const response = await iamApi.getUsers();
            users.value = UserAssembler.toEntitiesFromResponse(response);
            usersLoaded.value = true;
            return users.value;
        } catch (error) {
            errors.value.push(error);
            return [];
        }
    }

    function fetchUsers() {
        fetchUsersAsync();
    }

    async function fetchAdminsAsync() {
        try {
            const response = await iamApi.getAdmins();
            admins.value = AdminAssembler.toEntitiesFromResponse(response);
            adminsLoaded.value = true;
            return admins.value;
        } catch (error) {
            errors.value.push(error);
            return [];
        }
    }

    function fetchAdmins() {
        fetchAdminsAsync();
    }

    async function loadProfileFromSession() {
        const session = readAuthSession();
        await Promise.all([fetchUsersAsync(), fetchAdminsAsync()]);

        const user =
            (session?.userId && users.value.find((u) => Number(u.id) === Number(session.userId))) ||
            users.value.find((u) => u.email === session?.email) ||
            users.value.find((u) => u.role === (session?.role ?? 'ADMIN')) ||
            users.value[0] ||
            null;

        profileUser.value = user;

        const admin =
            admins.value.find((a) => Number(a.user_id ?? a.users_id) === Number(user?.id)) ||
            admins.value.find((a) => a.entity_code === session?.entityCode) ||
            admins.value[0] ||
            null;

        profileEntityCode.value = admin?.entity_code ?? session?.entityCode ?? '';
        profileEntityName.value = admin?.entity_name ?? session?.entityName ?? '';

        profileEstablishment.value = admin
            ? { establishment_name: admin.entity_name }
            : null;

        profilePlanApi.value = session?.plan ?? 'BASIC';
    }

    function getUserById(id) {
        const idNum = parseInt(id, 10);
        return users.value.find((user) => user.id === idNum);
    }

    function getAdminById(id) {
        const idNum = parseInt(id, 10);
        return admins.value.find((admin) => admin.id === idNum);
    }

    // ─── Authentication use cases ─────────────────────────────────────────────────

    /**
     * Signs in without choosing a portal first; the backend role decides the home.
     * @param {string} email
     * @param {string} password
     * @returns {Promise<Object>} Result with session and destination route name.
     */
    async function login(email, password) {
        const command = new SignInCommand({ email, password, segment: null });
        if (!command.email || !command.password) {
            return { ok: false, error: 'invalidCredentials' };
        }

        try {
            const result = await signInReal(command);
            if (!result.ok) return result;
            const isAdmin = result.session.role === 'ADMIN';
            localStorage.setItem('userRole', isAdmin ? 'health-entity' : 'operational-staff');
            return {
                ok: true,
                session: result.session,
                notAssigned: result.session.notAssigned,
                home: isAdmin ? 'home-health-entity' : 'home-operational-staff',
            };
        } catch (err) {
            const status = err?.response?.status;
            if (status === 401 || status === 400) return { ok: false, error: 'invalidCredentials' };
            return { ok: false, error: 'network' };
        }
    }

    /**
     * Signs a health-entity administrator in.
     * @param {string} email
     * @param {string} password
     * @returns {Promise<{ok: true, session: Object} | {ok: false, error: string}>}
     */
    async function loginHealthEntity(email, password) {
        const command = new SignInCommand({ email, password, segment: 'health-entity' });
        if (!command.email || !command.password) {
            return { ok: false, error: 'invalidCredentials' };
        }

        try {
            const result = await signInReal(command);
            if (!result.ok) return result;
            localStorage.setItem('userRole', 'health-entity');
            return { ok: true, session: result.session };
        } catch (err) {
            const status = err?.response?.status;
            if (status === 401 || status === 400) return { ok: false, error: 'invalidCredentials' };
            return { ok: false, error: 'network' };
        }
    }

    /**
     * Signs an operational-staff operator in.
     * @param {string} email
     * @param {string} password
     * @returns {Promise<Object>} Result carrying the session and assignment status.
     */
    async function loginOperationalStaff(email, password) {
        const command = new SignInCommand({ email, password, segment: 'operational-staff' });
        if (!command.email || !command.password) {
            return { ok: false, error: 'invalidCredentials' };
        }

        try {
            const result = await signInReal(command);
            if (!result.ok) return result;
            localStorage.setItem('userRole', 'operational-staff');
            return { ok: true, session: result.session, notAssigned: result.session.notAssigned };
        } catch (err) {
            const status = err?.response?.status;
            if (status === 401 || status === 400) return { ok: false, error: 'invalidCredentials' };
            return { ok: false, error: 'network' };
        }
    }

    /**
     * Stores the first step of a health-entity registration in the pending flow.
     * @param {Object} form - Registration form data.
     * @returns {Promise<{ok: boolean, error?: string}>}
     */
    async function startHealthEntityRegistration(form) {
        const command = new RegisterHealthEntityCommand(form ?? {});
        if (!command.isComplete()) {
            return { ok: false, error: 'required' };
        }
        writePendingRegistration({
            segment: 'health-entity',
            name: command.name,
            email: command.email,
            password: command.password,
            entityName: command.entityName,
        });
        return { ok: true };
    }

    /**
     * Persists the plan chosen during the registration flow.
     * @param {string} catalogPlanId - Catalog plan identifier (basic | premium | enterprise).
     */
    function saveRegistrationPlan(catalogPlanId) {
        writePendingPlan({
            catalogPlanId,
            planApiValue: Subscription.catalogIdToApiPlan(catalogPlanId),
            flow: 'registration',
        });
    }

    /**
     * Demo payment (UI only) then health-entity sign-up on the real API.
     * @param {Object} payment - Card fields from the billing screen (mock).
     * @returns {Promise<Object>} Result of the registration.
     */
    async function completeHealthEntityRegistration(payment) {
        const paymentValidation = validateDemoPayment(payment);
        if (!paymentValidation.valid) {
            return { ok: false, errors: paymentValidation.errors, phase: 'payment' };
        }

        const pending = readPendingRegistration();
        const plan = readPendingPlan();
        if (!pending || pending.segment !== 'health-entity') {
            return { ok: false, error: 'missingRegistration', phase: 'registration' };
        }
        if (!plan?.planApiValue) {
            return { ok: false, error: 'missingPlan', phase: 'registration' };
        }

        await simulateDemoPaymentProcessing();

        try {
            const today = new Date().toISOString().split('T')[0];
            await iamApi.createUser({
                    name: pending.name,
                    dni: '00000000',
                    email: pending.email,
                    phone: '',
                    job_title: 'Administrador',
                    entry_date: today,
                    role: 'Admin',
                    password: pending.password,
                    photo: '',
                    entity_name: pending.entityName,
                });
            } catch (err) {
                console.error('Registration failed:', err?.response?.data ?? err.message);
                const status = err?.response?.status;
                const message = String(err?.response?.data?.error ?? err?.response?.data?.detail ?? '').toLowerCase();
                if (status === 400 && message.includes('email already exists')) {
                    return { ok: false, error: 'emailExists', phase: 'registration', paymentApproved: true };
                }
                if (status === 400 && message.includes('admin')) {
                    return { ok: false, error: 'registrationFailed', phase: 'registration', paymentApproved: true };
                }
                if (status === 500) {
                    return { ok: false, error: 'serverError', phase: 'registration', paymentApproved: true };
                }
                return { ok: false, error: 'network', phase: 'registration', paymentApproved: true };
            }

        clearRegistrationFlow();
        return { ok: true, email: pending.email, paymentApproved: true };
    }

    /**
     * Registers an operational-staff operator against an existing entity code.
     * @param {Object} form - Registration form data.
     * @returns {Promise<Object>} Result carrying the joined entity name.
     */
    async function registerOperationalStaff(form) {
        const command = new RegisterOperationalStaffCommand(form ?? {});
        if (!command.name || !command.email || !command.password) {
            return { ok: false, error: 'required' };
        }
        if (!command.entityCode) return { ok: false, error: 'entityCodeRequired' };

        try {
            const admins = (await iamApi.getAdmins()).data ?? [];
            const matchedAdmin = admins.find(
                (a) => String(a.entity_code || '').toUpperCase() === command.entityCode.toUpperCase(),
            );
            if (!matchedAdmin) return { ok: false, error: 'invalidEntityCode' };

            const today = new Date().toISOString().split('T')[0];
            await iamApi.createUser({
                name: command.name,
                dni: command.dni || '00000000',
                email: command.email,
                phone: command.phone || '',
                job_title: command.jobTitle || 'Operador',
                entry_date: today,
                role: 'Operator',
                password: command.password,
                photo: '',
                entity_code: matchedAdmin.entity_code,
            });

            return { ok: true, entityName: matchedAdmin.entity_name };
        } catch (err) {
            const status = err?.response?.status;
            if (status === 400) return { ok: false, error: 'emailExists' };
            return { ok: false, error: 'network' };
        }
    }

    /** Clears the active session and any in-progress registration flow. */
    function logout() {
        clearRegistrationFlow();
        writeAuthSession(null);
        localStorage.removeItem('userRole');
    }

    return {
        users,
        admins,
        errors,
        usersLoaded,
        adminsLoaded,
        usersCount,
        adminsCount,
        profileUser,
        profileEstablishment,
        profilePlanApi,
        profileEntityCode,
        profileEntityName,
        fetchUsers,
        fetchUsersAsync,
        fetchAdmins,
        fetchAdminsAsync,
        loadProfileFromSession,
        getUserById,
        getAdminById,
        login,
        loginHealthEntity,
        loginOperationalStaff,
        startHealthEntityRegistration,
        saveRegistrationPlan,
        completeHealthEntityRegistration,
        registerOperationalStaff,
        logout,
    };
});

export default useIamStore;

import { readAuthSession } from './auth-session.js';

/**
 * Navigation guard that protects routes flagged with `meta.requiresAuth`
 * for anonymous visitors, redirecting them to the login screen.
 *
 * @param {import('vue-router').RouteLocationNormalized} to - Target route.
 * @param {import('vue-router').RouteLocationNormalized} from - Current route.
 * @returns {boolean | { name: string }} `true` when navigation is allowed, otherwise a redirect target.
 */
export const authenticationGuard = (to, from) => {
    const requiresAuth = to.matched.some((record) => record.meta?.requiresAuth);
    const isAnonymous = !readAuthSession();
    if (requiresAuth && isAnonymous) {
        return { name: 'login' };
    }
    return true;
};

/**
 * Application service store for the Logistics bounded context.
 * All data is loaded from the Render REST API.
 *
 * @module useLogisticsStore
 */
import { defineStore } from 'pinia';
import { computed, ref } from 'vue';
import { LogisticsApi } from '../infrastructure/logistics-api.js';
import { TransportAssembler } from '../infrastructure/transport.assembler.js';

const logisticsApi = new LogisticsApi();

function generateSensorReading(typeOfMedication) {
    const r = (min, max, dec = 1) => parseFloat((min + Math.random() * (max - min)).toFixed(dec));
    const door = Math.random() < 0.15 ? 'Open' : 'Closed';
    switch (String(typeOfMedication).toLowerCase()) {
        case 'refrigerated':
            return { temperature: r(2, 8), humidity: r(40, 60), light_intensity: r(0, 50), air_quality: r(350, 420), vibration: r(0.01, 0.08, 3), atmospheric_pressure: r(1010, 1015), suspended_particles: r(5, 15), door_status: door };
        case 'biological':
            return { temperature: r(-20, -15), humidity: r(20, 35), light_intensity: r(0, 30), air_quality: r(380, 450), vibration: r(0.00, 0.03, 3), atmospheric_pressure: r(1008, 1013), suspended_particles: r(3, 10), door_status: door };
        case 'controlled':
            return { temperature: r(15, 25), humidity: r(35, 55), light_intensity: r(100, 300), air_quality: r(400, 500), vibration: r(0.05, 0.15, 3), atmospheric_pressure: r(1005, 1015), suspended_particles: r(10, 30), door_status: door };
        default:
            return { temperature: r(18, 28), humidity: r(30, 60), light_intensity: r(50, 400), air_quality: r(350, 500), vibration: r(0.02, 0.12, 3), atmospheric_pressure: r(1005, 1020), suspended_particles: r(5, 25), door_status: door };
    }
}

const useLogisticsStore = defineStore('logistics', () => {
    const transports = ref([]);
    const errors = ref([]);
    const transportsLoaded = ref(false);
    let simulationInterval = null;

    const transportsCount = computed(() => (transportsLoaded.value ? transports.value.length : 0));

    async function fetchTransportsAsync() {
        try {
            const response = await logisticsApi.getTransports();
            transports.value = TransportAssembler.toEntitiesFromResponse(response);
            transportsLoaded.value = true;
            return transports.value;
        } catch (error) {
            errors.value.push(error);
            return [];
        }
    }

    function fetchTransports() {
        fetchTransportsAsync();
    }

    function getTransportById(id) {
        const idNum = parseInt(id, 10);
        return transports.value.find((t) => t.id === idNum);
    }

    async function createTransportAsync(transport) {
        const response = await logisticsApi.createTransport(transport);
        const entity = TransportAssembler.toEntityFromResource(response.data);
        transports.value.push(entity);
        return entity;
    }

    async function deleteTransportAsync(transport) {
        await logisticsApi.deleteTransport(transport.id, transport.establishment_id);
        transports.value = transports.value.filter((t) => t.id !== transport.id);
    }

    async function pushSimulatedReadings() {
        if (!transports.value.length) return;
        await Promise.allSettled(
            transports.value.map(async (transport) => {
                try {
                    const reading = generateSensorReading(transport.type_of_medication);
                    await logisticsApi.updateSensorData(transport.id, reading, transport.establishment_id);
                    const idx = transports.value.findIndex((t) => t.id === transport.id);
                    if (idx !== -1) transports.value[idx] = { ...transports.value[idx], ...reading };
                } catch { /* non-fatal */ }
            }),
        );
    }

    function startSimulation(intervalMs = 10000) {
        if (simulationInterval !== null) return;
        pushSimulatedReadings();
        simulationInterval = setInterval(pushSimulatedReadings, intervalMs);
    }

    function stopSimulation() {
        if (simulationInterval !== null) {
            clearInterval(simulationInterval);
            simulationInterval = null;
        }
    }

    return {
        transports,
        errors,
        transportsLoaded,
        transportsCount,
        fetchTransports,
        fetchTransportsAsync,
        getTransportById,
        createTransportAsync,
        deleteTransportAsync,
        pushSimulatedReadings,
        startSimulation,
        stopSimulation,
    };
});

