/**
 * Application service store for the Monitoring bounded context.
 * All data is loaded from the Render REST API.
 *
 * @module useMonitoringStore
 */
import { defineStore } from 'pinia';
import { computed, ref } from 'vue';
import { MonitoringApi } from '../infrastructure/monitoring-api.js';
import { DeviceAssembler } from '../infrastructure/device.assembler.js';

const monitoringApi = new MonitoringApi();

function generateSensorReading(typeOfMedication) {
    const r = (min, max, dec = 1) => parseFloat((min + Math.random() * (max - min)).toFixed(dec));
    const door = Math.random() < 0.15 ? 'Open' : 'Closed';
    switch (String(typeOfMedication).toLowerCase()) {
        case 'refrigerated':
            return { temperature: r(2, 8), humidity: r(40, 60), light_intensity: r(0, 50), air_quality: r(350, 420), vibration: r(0.01, 0.08, 3), atmospheric_pressure: r(1010, 1015), suspended_particles: r(5, 15), door_status: door };
        case 'biological':
            return { temperature: r(-20, -15), humidity: r(20, 35), light_intensity: r(0, 30), air_quality: r(380, 450), vibration: r(0.00, 0.03, 3), atmospheric_pressure: r(1008, 1013), suspended_particles: r(3, 10), door_status: door };
        case 'controlled':
            return { temperature: r(15, 25), humidity: r(35, 55), light_intensity: r(100, 300), air_quality: r(400, 500), vibration: r(0.05, 0.15, 3), atmospheric_pressure: r(1005, 1015), suspended_particles: r(10, 30), door_status: door };
        default:
            return { temperature: r(18, 28), humidity: r(30, 60), light_intensity: r(50, 400), air_quality: r(350, 500), vibration: r(0.02, 0.12, 3), atmospheric_pressure: r(1005, 1020), suspended_particles: r(5, 25), door_status: door };
    }
}

const useMonitoringStore = defineStore('monitoring', () => {
    const devices = ref([]);
    const errors = ref([]);
    const devicesLoaded = ref(false);
    let simulationInterval = null;

    const devicesCount = computed(() => (devicesLoaded.value ? devices.value.length : 0));

    function fetchDevices() {
        fetchDevicesAsync();
    }

    async function fetchDevicesAsync() {
        try {
            const response = await monitoringApi.getDevices();
            devices.value = DeviceAssembler.toEntitiesFromResponse(response);
            devicesLoaded.value = true;
            return devices.value;
        } catch (error) {
            errors.value.push(error);
            return [];
        }
    }

    function getDeviceById(id) {
        const idNum = parseInt(id, 10);
        return devices.value.find((d) => d.id === idNum);
    }

    async function createDeviceAsync(device) {
        const response = await monitoringApi.createDevice(device);
        const entity = DeviceAssembler.toEntityFromResource(response.data);
        devices.value.push(entity);
        return entity;
    }

    async function deleteDeviceAsync(device) {
        await monitoringApi.deleteDevice(device.id, device.establishment_id);
        const index = devices.value.findIndex((d) => d.id === device.id);
        if (index !== -1) devices.value.splice(index, 1);
        return true;
    }

    async function pushSimulatedReadings() {
        if (!devices.value.length) return;
        await Promise.allSettled(
            devices.value.map(async (device) => {
                try {
                    const reading = generateSensorReading(device.type_of_medication);
                    await monitoringApi.updateSensorData(device.id, reading, device.establishment_id);
                    const idx = devices.value.findIndex((d) => d.id === device.id);
                    if (idx !== -1) devices.value[idx] = { ...devices.value[idx], ...reading };
                } catch { /* retry next tick */ }
            }),
        );
    }

    function startSimulation(intervalMs = 10000) {
        if (simulationInterval !== null) return;
        pushSimulatedReadings();
        simulationInterval = setInterval(pushSimulatedReadings, intervalMs);
    }

    function stopSimulation() {
        if (simulationInterval !== null) {
            clearInterval(simulationInterval);
            simulationInterval = null;
        }
    }

    return {
        devices,
        errors,
        devicesLoaded,
        devicesCount,
        fetchDevices,
        fetchDevicesAsync,
        getDeviceById,
        createDeviceAsync,
        deleteDeviceAsync,
        pushSimulatedReadings,
        startSimulation,
        stopSimulation,
    };
});

export default useMonitoringStore;

/**
 * Device (sensor) entity within the Monitoring bounded context.
 *
 * @class Device
 */
export class Device {
    constructor({
        id = null,
        exact_location = '',
        type_of_medication = '',
        temperature = null,
        humidity = null,
        light_intensity = null,
        air_quality = null,
        vibration = null,
        door_status = '',
        atmospheric_pressure = null,
        suspended_particles = null,
        created_at = '',
        updated_at = '',
        establishment_id = null,
        enabled_sensors = null,
    } = {}) {
        this.id = id;
        this.exact_location = exact_location;
        this.type_of_medication = type_of_medication;
        this.temperature = temperature;
        this.humidity = humidity;
        this.light_intensity = light_intensity;
        this.air_quality = air_quality;
        this.vibration = vibration;
        this.door_status = door_status;
        this.atmospheric_pressure = atmospheric_pressure;
        this.suspended_particles = suspended_particles;
        this.created_at = created_at;
        this.updated_at = updated_at;
        this.establishment_id = establishment_id;
        // Parse enabled_sensors JSON string from backend
        if (typeof enabled_sensors === 'string' && enabled_sensors.trim().startsWith('{')) {
            try { this.enabled_sensors = JSON.parse(enabled_sensors); } catch { this.enabled_sensors = null; }
        } else if (enabled_sensors && typeof enabled_sensors === 'object') {
            this.enabled_sensors = enabled_sensors;
        } else {
            this.enabled_sensors = null;
        }
    }

    // ── Sensor metric definitions ─────────────────────────────────────────────

    static METRIC_DEFS = [
        { key: 'temperature', field: 'temperature', labelKey: 'sensorTemp', unit: '°C', decimals: 1 },
        { key: 'humidity', field: 'humidity', labelKey: 'sensorHumidity', unit: '% RH', decimals: 1 },
        { key: 'light', field: 'light_intensity', altFields: ['lightIntensity', 'lux'], labelKey: 'sensorLight', unit: 'LUX', decimals: 0 },
        { key: 'vibration', field: 'vibration', labelKey: 'sensorVibration', unit: 'm/s²', decimals: 2 },
        { key: 'door', field: 'door_status', altFields: ['doorStatus', 'door'], labelKey: 'sensorDoor', discrete: true },
        { key: 'co2', field: 'co2', altFields: ['air_quality', 'co2_ppm'], labelKey: 'sensorCo2', unit: 'CO₂ PPM', decimals: 0 },
        { key: 'pressure', field: 'atmospheric_pressure', altFields: ['pressure'], labelKey: 'sensorPressure', unit: 'hPa', decimals: 1 },
        { key: 'pm25', field: 'pm25', altFields: ['pm2_5', 'suspended_particles'], labelKey: 'sensorPm25', unit: 'PM2.5', decimals: 1 },
    ];

    static #THRESHOLDS = {
        temperature: { min: 2, max: 8, warnBelow: 2.5, warnAbove: 7, safe: 4.5, drift: 0.12 },
        humidity:    { min: 35, max: 65, warnBelow: 38, warnAbove: 60, safe: 47, drift: 0.6 },
        light:       { min: 0, max: 350, warnAbove: 280, safe: 120, drift: 8 },
        vibration:   { min: 0, max: 0.12, warnAbove: 0.08, safe: 0.03, drift: 0.008 },
        co2:         { min: 0, max: 900, warnAbove: 700, safe: 420, drift: 12 },
        pressure:    { min: 990, max: 1030, warnBelow: 992, warnAbove: 1026, safe: 1013.2, drift: 0.4 },
        pm25:        { min: 0, max: 30, warnAbove: 22, safe: 12, drift: 0.5 },
    };

    // ── Helpers ───────────────────────────────────────────────────────────────

    static toNum(v) {
        if (v == null || (typeof v === 'string' && v.trim() === '')) return null;
        const n = Number(v);
        return Number.isFinite(n) ? n : null;
    }

    static findMetricDef(key) {
        return Device.METRIC_DEFS.find((d) => d.key === key);
    }

    static readField(dev, def) {
        if (!dev) return null;
        const primary = dev[def.field];
        if (primary != null && primary !== '') return primary;
        for (const alt of def.altFields || []) {
            const v = dev[alt];
            if (v != null && v !== '') return v;
        }
        return null;
    }

    // ── Threshold evaluation ──────────────────────────────────────────────────

    static evaluateMetric(key, rawValue) {
        if (key === 'door') {
            const door = String(rawValue ?? '').toUpperCase();
            if (!door) return 'unknown';
            return door.includes('OPEN') || door.includes('ABIERTA') ? 'critical' : 'ok';
        }
        const value = Device.toNum(rawValue);
        if (value == null) return 'unknown';
        const t = Device.#THRESHOLDS[key];
        if (!t) return 'ok';
        if (t.max != null && value > t.max) return 'critical';
        if (t.min != null && value < t.min) return 'critical';
        if (t.warnAbove != null && value > t.warnAbove) return 'warning';
        if (t.warnBelow != null && value < t.warnBelow) return 'warning';
        return 'ok';
    }

    static isOutOfRange(key, rawValue) {
        const st = Device.evaluateMetric(key, rawValue);
        return st === 'warning' || st === 'critical';
    }

    static getSafeValue(key) {
        if (key === 'door') return 'CLOSED';
        return Device.#THRESHOLDS[key]?.safe ?? null;
    }

    static driftValue(key, current) {
        const t = Device.#THRESHOLDS[key];
        if (!t) return current;
        const base = Device.toNum(current) ?? t.safe;
        let next = base + (Math.random() - 0.48) * t.drift * 2;
        if (t.min != null) next = Math.max(t.min - t.drift * 3, next);
        if (t.max != null) next = Math.min(t.max + t.drift * 4, next);
        const decimals = Device.findMetricDef(key)?.decimals ?? 1;
        return Number(next.toFixed(decimals));
    }

    // ── Formatting ────────────────────────────────────────────────────────────

    static formatMetric(def, rawValue) {
        if (def.discrete) return String(rawValue ?? '—') || '—';
        const value = Device.toNum(rawValue);
        if (value == null) return '—';
        return `${value.toFixed(def.decimals ?? 1)} ${def.unit}`;
    }

    static formatSafeMetric(key) {
        const def = Device.findMetricDef(key);
        if (!def) return '—';
        return Device.formatMetric(def, Device.getSafeValue(key));
    }

    // ── Live snapshot ─────────────────────────────────────────────────────────

    static initLiveSnapshot(dev) {
        const snap = {};
        for (const def of Device.METRIC_DEFS) {
            // Only initialize metrics that are enabled for this device
            const enabled = dev?.enabled_sensors;
            const hasEnabledMap = enabled && typeof enabled === 'object' && Object.keys(enabled).length > 0;
            if (hasEnabledMap && enabled[def.key] !== true) continue;

            if (def.discrete) {
                snap[def.key] = Device.readField(dev, def) ?? 'CLOSED';
            } else {
                const v = Device.readField(dev, def);
                snap[def.key] = v != null && v !== '' ? Device.toNum(v) : Device.getSafeValue(def.key);
            }
        }
        return snap;
    }

    static isMetricEnabled(def, dev, liveSnap) {
        const enabled = dev?.enabled_sensors;
        // If enabled_sensors is a parsed object with keys, only show explicitly enabled sensors
        if (enabled && typeof enabled === 'object' && Object.keys(enabled).length > 0) {
            return enabled[def.key] === true;
        }
        // No enabled_sensors (old device or empty): show everything
        if (def.discrete) return true;
        return liveSnap[def.key] != null;
    }
}

import { createRouter, createWebHistory } from "vue-router";
import Layout from "./shared/presentation/components/layout.vue";
import Login from "./iam/presentation/views/login.vue";
import Home from "./shared/presentation/views/home.vue";
import establishmentRoutes from "./establishment/presentation/establishment-routes.js";
import monitoringRoutes from "./monitoring/presentation/monitoring-routes.js";
import logisticsRoutes from "./logistics/presentation/logistics-routes.js";
import subscriptionsRoutes from "./subscriptions/presentation/subscriptions-routes.js";
import iamRoutes from "./iam/presentation/iam-routes.js";
import iamAuthRoutes from "./iam/presentation/iam-auth-routes.js";
import { authenticationGuard } from "./iam/infrastructure/authentication.guard.js";

const pageNotFound = () => import('./shared/presentation/views/page-not-found.vue');
const iamAuthLayout = () => import('./iam/presentation/views/auth-layout.vue');
const authSessionLayout = () => import('./iam/presentation/views/auth-session-layout.vue');
const register = () => import('./iam/presentation/views/register.vue');

const routes = [
    {
        path: '/',
        component: authSessionLayout,
        meta: { requiresAuth: false },
        children: [
            {
                path: '',
                redirect: { name: 'login' },
            },
            {
                path: 'login',
                name: 'login',
                component: Login,
                meta: { title: 'Login', requiresAuth: false },
            },
            {
                path: 'iam/auth/register',
                name: 'iam-register',
                component: register,
                meta: { title: 'Register', requiresAuth: false },
            },
        ],
    },
    {
        path: '/iam/auth',
        component: iamAuthLayout,
        children: iamAuthRoutes,
        meta: { requiresAuth: false }
    },
    {
        path: '/',
        component: Layout,
        children: [
            { path: 'home', name: 'home', component: Home, meta: { title: 'Home' } },
            { path: 'home-health-entity', redirect: { name: 'home-health-entity' } },
            { path: 'home-operational-staff', redirect: { name: 'home-operational-staff' } },
            { path: 'profile', redirect: () => {
                try {
                    const raw = sessionStorage.getItem('meditrack_auth_session');
                    const session = raw ? JSON.parse(raw) : null;
                    const profileId = session?.userId ?? session?.id ?? 'me';
                    return { name: 'profile', params: { profileId: String(profileId) } };
                } catch {
                    return { name: 'profile', params: { profileId: 'me' } };
                }
            }},
            { path: 'establishment', name: 'establishment', children: establishmentRoutes },
            { path: 'monitoring', name: 'monitoring', children: monitoringRoutes },
            { path: 'logistics', name: 'logistics', children: logisticsRoutes },
            { path: 'subscriptions', name: 'subscriptions', children: subscriptionsRoutes },
            { path: 'iam', name: 'iam', children: iamRoutes },
            { path: '', redirect: '/login' }
        ]
    },
    { path: '/:pathMatch(.*)*', name: 'not-found', component: pageNotFound, meta: { title: 'Page Not Found' } }
];

const router = createRouter({
    history: createWebHistory(import.meta.env.BASE_URL),
    routes: routes,
});

router.beforeEach((to, from) => {
    let baseTitle = 'KairoLabs';
    document.title = `${baseTitle} - ${to.meta['title']}`;
    return authenticationGuard(to, from);
});

