export function updateMockOperator(id, patch) {
    const op = operators.find((o) => Number(o.id) === Number(id));
    if (!op) return null;
    Object.assign(op, patch);
    return { ...op };
}

export function deleteMockOperator(id) {
    const idx = operators.findIndex((o) => Number(o.id) === Number(id));
    if (idx === -1) return false;
    operators.splice(idx, 1);
    return true;
}

export function findMockOperatorByUserId(userId) {
    const uidNum = Number(userId);
    return operators.find((o) => Number(o.users_id) === uidNum) ?? null;
}

export function findMockUserByEmail(email) {
    const normalized = String(email || '').trim().toLowerCase();
    return users.find((u) => u.email.toLowerCase() === normalized) ?? null;
}

export function findMockAdminByEntityCode(code) {
    const normalized = String(code || '').trim().toUpperCase();
    return admins.find((a) => String(a.entity_code || '').toUpperCase() === normalized) ?? null;
}

export function addMockUser(payload) {
    const email = String(payload.email || '').trim().toLowerCase();
    if (findMockUserByEmail(email)) {
        const err = new Error('Email already exists');
        err.response = { status: 400, data: { error: 'Email already exists' } };
        throw err;
    }

    const roleRaw = String(payload.role || 'Operator');
    const isAdmin = roleRaw.toLowerCase() === 'admin';
    const user = {
        id: uid(),
        name: payload.name || '',
        dni: payload.dni || '00000000',
        email,
        phone: payload.phone || '',
        job_title: payload.job_title || (isAdmin ? 'Administrador' : 'Operador'),
        entry_date: payload.entry_date || new Date().toISOString().slice(0, 10),
        role: isAdmin ? 'ADMIN' : 'OPERATOR',
        password: payload.password || 'demo123',
        photo: payload.photo || '',
        created_at: new Date().toISOString(),
        entity_code: payload.entity_code || null,
    };
    users.push(user);

    if (isAdmin) {
        const entityCode =
            payload.entity_code ||
            `KL-${String(user.id).padStart(4, '0')}`;
        const admin = {
            id: uid(),
            entity_name: payload.entity_name || 'Entidad KairoLabs',
            entity_code: entityCode,
            schedule: 'Lun-Vie 08:00-18:00',
            users_id: user.id,
            user_id: user.id,
        };
        admins.push(admin);
        user.entity_code = entityCode;
        return { user: { ...user }, admin: { ...admin } };
    }

    const operator = {
        id: uid(),
        alerts_answered: 0,
        schedule: 'Mañana 06:00-14:00',
        establishment_id: null,
        users_id: user.id,
    };
    operators.push(operator);
    return { user: { ...user }, operator: { ...operator } };
}

export function authenticateMockUser(email, password) {
    const user = findMockUserByEmail(email);
    if (!user || String(user.password) !== String(password)) {
        const err = new Error('Invalid credentials');
        err.response = { status: 401, data: { error: 'Invalid credentials' } };
        throw err;
    }
    return {
        user: {
            id: user.id,
            email: user.email,
            name: user.name,
            role: String(user.role).toLowerCase() === 'admin' ? 'admin' : 'operator',
        },
        token: `mock-token-${user.id}-${Date.now()}`,
    };
}

/**
 * IAM application facade — demo profile orchestration across IAM, Establishment and Subscriptions APIs.
 *
 * @module profile-demo.facade
 */
import { IamApi } from '../infrastructure/iam-api.js';
import { UserAssembler } from '../infrastructure/user.assembler.js';
import { EstablishmentApi } from '../../establishment/infrastructure/establishment-api.js';
import { EstablishmentAssembler } from '../../establishment/infrastructure/establishment.assembler.js';
import { SubscriptionsApi } from '../../subscriptions/infrastructure/subscriptions-api.js';
import { SubscriptionAssembler } from '../../subscriptions/infrastructure/subscription.assembler.js';

const iamApi = new IamApi();
const establishmentApi = new EstablishmentApi();
const subscriptionsApi = new SubscriptionsApi();

function pickRandom(arr) {
    if (!arr?.length) return null;
    return arr[Math.floor(Math.random() * arr.length)];
}

/**
 * @param {{ persistedUserId?: number|null, planFromSession?: Object|null }} [options]
 * @returns {Promise<Object>}
 */
export async function fetchProfileDemoFromApis(options = {}) {
    const [usersRes, establishmentsRes, subscriptionsRes] = await Promise.all([
        iamApi.getUsers(),
        establishmentApi.getEstablishments(),
        subscriptionsApi.getSubscriptions(),
    ]);

    const users = UserAssembler.toEntitiesFromResponse(usersRes);
    const establishments = EstablishmentAssembler.toEntitiesFromResponse(establishmentsRes);
    const subscriptions = SubscriptionAssembler.toEntitiesFromResponse(subscriptionsRes);

    const user =
        (options.persistedUserId && users.find((u) => u.id === options.persistedUserId)) ??
        pickRandom(users);

    const establishment =
        establishments.find((e) => e.admin_id === user?.id) ?? pickRandom(establishments);

    const subscription =
        subscriptions.find((s) => s.admin_id === user?.id) ?? pickRandom(subscriptions);

    const randomSub = pickRandom(subscriptions);
    const planApi =
        options.planFromSession?.planApiValue != null
            ? options.planFromSession.planApiValue
            : randomSub?.plan ?? 'BASIC';
    const benefitsEndDate =
        options.planFromSession?.benefitsEndDate != null
            ? options.planFromSession.benefitsEndDate
            : randomSub?.end_date ?? subscription?.end_date ?? null;

    return {
        user,
        establishment,
        subscription,
        planApi,
        benefitsEndDate,
    };
}

/**
 * Subscription entity within the Subscriptions bounded context.
 *
 * @class Subscription
 */
export class Subscription {
    constructor({
        id = null,
        admin_id = null,
        plan = '',
        start_date = '',
        end_date = '',
        status = '',
        created_at = '',
    } = {}) {
        this.id = id;
        this.admin_id = admin_id;
        this.plan = plan;
        this.start_date = start_date;
        this.end_date = end_date;
        this.status = status;
        this.created_at = created_at;
    }

    // ── Plan catalog ──────────────────────────────────────────────────────────

    static PLAN_CATALOG_ORDER = ['basic', 'premium', 'enterprise'];

    static PLAN_CATALOG = {
        basic: {
            id: 'basic',
            apiPlan: 'BASIC',
            recommended: false,
            limits: { establishments: 5, staticDevices: 40, vehicleDevices: 40 },
            customParameters: false,
        },
        premium: {
            id: 'premium',
            apiPlan: 'PREMIUM',
            recommended: true,
            limits: { establishments: 40, staticDevices: 200, vehicleDevices: 200 },
            customParameters: true,
        },
        enterprise: {
            id: 'enterprise',
            apiPlan: 'ENTERPRISE',
            recommended: false,
            limits: { establishments: 400, staticDevices: 800, vehicleDevices: 800 },
            customParameters: true,
        },
    };

    static getPlanByCatalogId(catalogId) {
        const id = String(catalogId || 'basic').toLowerCase();
        return Subscription.PLAN_CATALOG[id] ?? Subscription.PLAN_CATALOG.basic;
    }

    static apiPlanToCatalogId(apiPlan) {
        const p = String(apiPlan || 'BASIC').toUpperCase();
        const found = Subscription.PLAN_CATALOG_ORDER.find(
            (id) => Subscription.PLAN_CATALOG[id].apiPlan === p,
        );
        return found ?? 'basic';
    }

    static catalogIdToApiPlan(catalogId) {
        return Subscription.getPlanByCatalogId(catalogId).apiPlan;
    }
}
